create sequence public.service_order_number_sequence start 1;
create or replace function public.next_service_order_number() returns text language sql volatile set search_path=public as $$ select format('OS-%s-%s',to_char(current_date,'YYYY'),lpad(nextval('public.service_order_number_sequence')::text,6,'0')); $$;
create table public.service_orders(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,order_number text not null unique default public.next_service_order_number(),ticket_id uuid not null references public.tickets(id) on delete restrict,contract_id uuid references public.contracts(id) on delete set null,location_id uuid references public.customer_locations(id) on delete set null,technician_id uuid references public.technicians(id) on delete set null,supplier_id uuid references public.suppliers(id) on delete set null,status text not null default 'TRIAGE' check(status in('TRIAGE','DISPATCHED','TRAVELING','CHECKED_IN','IN_SERVICE','COMPLETED','VALIDATED','CANCELLED')),scheduled_at timestamptz,dispatched_at timestamptz,checked_in_at timestamptz,checked_out_at timestamptz,completed_at timestamptz,customer_acceptance text,notes text,created_at timestamptz not null default now(),created_by uuid references public.user_profiles(id) on delete set null,updated_at timestamptz not null default now(),updated_by uuid references public.user_profiles(id) on delete set null,unique(ticket_id));
create table public.service_order_events(id uuid primary key default gen_random_uuid(),service_order_id uuid not null references public.service_orders(id) on delete restrict,organization_id uuid not null references public.organizations(id) on delete restrict,event_type text not null check(event_type in('CREATED','DISPATCHED','TRAVELING','CHECK_IN','SERVICE_STARTED','CHECK_OUT','COMPLETED','VALIDATED','CANCELLED')),occurred_at timestamptz not null default now(),actor_id uuid references public.user_profiles(id) on delete set null,details jsonb not null default '{}'::jsonb);
create index service_orders_org_status_idx on public.service_orders(organization_id,status,scheduled_at); create index service_order_events_order_idx on public.service_order_events(service_order_id,occurred_at);
create trigger service_orders_updated before update on public.service_orders for each row execute function public.set_updated_at();
alter table public.service_orders enable row level security; alter table public.service_order_events enable row level security;
create policy "members read service orders" on public.service_orders for select to authenticated using(public.is_organization_member(organization_id));
create policy "managers manage service orders" on public.service_orders for all to authenticated using(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER','DISPATCHER']::public.platform_role[])) with check(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER','DISPATCHER']::public.platform_role[]));
create policy "members read service order events" on public.service_order_events for select to authenticated using(public.is_organization_member(organization_id));
